@startuml

class Boeing {
  + Name : string
}

class Airline {
  + Name : string
}

class Employee {
  + Name : string
  + EmployeeID : string
}

class Salesperson {
  + SalesID : string
}

class Contract {
  + ContractID : string
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : double
  + Options : string
  + DeliveryDate : date
}

class Airplane {
  + SerialNumber : string
  + Model : string
}

Employee "1" -- "0..*" Salesperson
Salesperson "1" -- "1..*" Contract
Contract "1" o-- "1..*" Acquisition
Acquisition "1" -- "1" Airplane
Boeing "1" -- "0..*" Contract
Airline "1" -- "0..*" Contract
Airline "0..1" o-- "0..1" Airline : motherOf
Airline "0..1" o-- "0..1" Airline : daughterOf

@enduml

